"use client";

import { useState } from "react";
import Link from "next/link";
import styles from "./discover.module.css";

const MOCK_PROFILES = [
  {
    id: 1,
    name: "Elena",
    age: 26,
    bio: "UX Designer by day, amateur DJ by night. Let's trade Spotify playlists.",
    tags: ["Creative", "Spontaneous", "Chill"],
    image: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    distance: "5 miles away"
  },
  {
    id: 2,
    name: "Marcus",
    age: 29,
    bio: "Coffee addict and weekend hiker. Looking for someone to get lost in the mountains with.",
    tags: ["Adventurous", "Analytical", "Outgoing"],
    image: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    distance: "12 miles away"
  },
  {
    id: 3,
    name: "Sophia",
    age: 24,
    bio: "Plant mom and aspiring chef. Will cook for you if you buy the wine.",
    tags: ["Empathetic", "Chill", "Creative"],
    image: "https://images.unsplash.com/photo-1517841905240-472988babdf9?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    distance: "2 miles away"
  }
];

export default function Discover() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [animationClass, setAnimationClass] = useState("");

  const handleAction = (type: "pass" | "spark") => {
    setAnimationClass(type === "pass" ? styles.slideLeft : styles.slideRight);
    
    setTimeout(() => {
      if (currentIndex < MOCK_PROFILES.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setAnimationClass("");
      } else {
        // No more profiles
        setCurrentIndex(-1);
      }
    }, 300);
  };

  const currentProfile = currentIndex >= 0 ? MOCK_PROFILES[currentIndex] : null;

  return (
    <main className={styles.container}>
      <header className={styles.header}>
        <div className="text-aura" style={{ fontWeight: 700, fontSize: "1.5rem" }}>Synqra</div>
        <Link href="/premium" className={styles.premiumBadge}>
          Get Plus
        </Link>
      </header>

      <div className={styles.cardContainer}>
        {currentProfile ? (
          <div className={`${styles.profileCard} ${animationClass}`} style={{ backgroundImage: `url(${currentProfile.image})` }}>
            <div className={styles.cardOverlay}>
              <div className={styles.profileInfo}>
                <div className={styles.nameAge}>
                  <h2>{currentProfile.name}, {currentProfile.age}</h2>
                  <span className={styles.distance}>{currentProfile.distance}</span>
                </div>
                
                <p className={styles.bio}>{currentProfile.bio}</p>
                
                <div className={styles.tags}>
                  {currentProfile.tags.map(tag => (
                    <span key={tag} className={styles.tag}>{tag}</span>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className={`glass-card ${styles.emptyState}`}>
            <div className={styles.pulseRing}></div>
            <h3>You've seen everyone!</h3>
            <p>Expand your distance or check back later for more matches.</p>
            <button className="btn-glass" onClick={() => setCurrentIndex(0)} style={{ marginTop: "20px" }}>
              Reset Discover
            </button>
          </div>
        )}
      </div>

      {currentProfile && (
        <div className={styles.actions}>
          <button className={`${styles.actionBtn} ${styles.passBtn}`} onClick={() => handleAction("pass")}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
          </button>
          <button className={`${styles.actionBtn} ${styles.sparkBtn}`} onClick={() => handleAction("spark")}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>
          </button>
        </div>
      )}
    </main>
  );
}
